// Keep prize labels near their badge, inside the art area, and out of each
// other's way. If a small quadrant fills up, use another short wave.
const GAP = 4;

function nearestPosition(item, area, blockers) {
  const right = area.right - item.width, bottom = area.bottom - item.height;
  if (right < area.left || bottom < area.top) return null;
  const x = item.x - item.width / 2, y = item.y - item.height / 2 - 18;
  // The closest free rectangle touches either the preferred position, an area
  // boundary, or an obstacle edge. Check those coordinates instead of allocating
  // and sorting every 3px grid point for every prize. Work no longer grows with
  // the widget's pixel area.
  const xs = new Set([area.left, right, Math.max(area.left, Math.min(right, x))]);
  const ys = new Set([area.top, bottom, Math.max(area.top, Math.min(bottom, y))]);
  for (const block of blockers) {
    for (const edge of [block.left - item.width - GAP, block.left + block.width + GAP]) {
      if (edge >= area.left && edge <= right) xs.add(edge);
    }
    for (const edge of [block.top - item.height - GAP, block.top + block.height + GAP]) {
      if (edge >= area.top && edge <= bottom) ys.add(edge);
    }
  }
  let choice = null, best = Infinity;
  const columns = [...xs].sort((a, b) => a - b);
  for (const top of [...ys].sort((a, b) => a - b)) {
    for (const left of columns) {
      const score = (left - x) ** 2 + (top - y) ** 2;
      if (score >= best) continue;
      if (blockers.some(block => left < block.left + block.width + GAP
        && left + item.width + GAP > block.left
        && top < block.top + block.height + GAP
        && top + item.height + GAP > block.top)) continue;
      best = score;
      choice = { left, top, width: item.width, height: item.height };
    }
  }
  return choice;
}

export function layoutWinFlights(items, area, obstacles = []) {
  const waves = [];
  const output = [];

  // Reserve the widest amounts first; preserve badge identity in the output.
  const ordered = items.map((item, index) => ({ ...item, index }))
    .sort((a, b) => b.width - a.width || a.index - b.index);
  for (const item of ordered) {
    let choice;
    let wave = 0;
    for (; wave <= waves.length; wave++) {
      choice = nearestPosition(item, area, obstacles.concat(waves[wave] || []));
      if (choice) break;
    }
    // If no free position exists, the caller leaves this prize to the badge's
    // manual popup. Never cover the receipt or center to force a flight.
    if (!choice) { output[item.index] = null; continue; }
    waves[wave] ||= [];
    const slot = waves[wave].length;
    waves[wave].push(choice);
    output[item.index] = { left: choice.left, top: choice.top, slot, wave };
  }
  const starts = [];
  waves.forEach((wave, index) => {
    starts[index] = index === 0 ? 0
      : starts[index - 1] + 1300 + (waves[index - 1].length - 1) * 60;
  });
  return output.map(position => {
    if (!position) return null;
    const { slot, ...rest } = position;
    return { ...rest, delay: starts[position.wave] + slot * 60 };
  });
}
